import{S as c,o as d,c as r,a9 as n,B as i}from"./chunks/framework.DxG24V0C.js";const t="/agentsrc/images/codex/06-execution-pipeline.svg",l="/agentsrc/images/codex/06-cross-platform-sandbox.svg",u=JSON.parse('{"title":"Codex 沙箱引擎：如何把 AI 关进操作系统的笼子？","description":"","frontmatter":{"title":"Codex 沙箱引擎：如何把 AI 关进操作系统的笼子？"},"headers":[],"relativePath":"codex/06-sandboxing.md","filePath":"codex/06-sandboxing.md","lastUpdated":1788847143000}'),s={name:"codex/06-sandboxing.md"},m=Object.assign(s,{setup(p){const o=[{question:"在 Codex 中，当大模型生成了一条 shell_command 后，其真实的执行链路顺序是怎样的？",options:["底层执行 → Sandbox 封装 → 策略解析 → 执行审批","策略解析 → Sandbox 封装 → 底层执行 → 执行审批","策略解析 → 执行审批 → Sandbox 封装 → 底层执行","Sandbox 封装 → 执行审批 → 策略解析 → 底层执行"],correct:2,explanation:"真实的执行链路是：ExecPolicyManager 先解析策略，若需审批则发出请求（挂起等待用户）；通过后交由 SandboxManager 进行沙箱参数封装，最后启动子进程执行。"},{question:"在 Linux 平台上，Codex 目前实现文件系统隔离的主力防线机制是什么？",options:["使用 Docker 容器虚拟化技术，将每个工具执行放在独立的隔离容器中","使用 Linux 内核的 Landlock 特性，严格限制进程级的文件访问权限","使用 bubblewrap 挂载受限的文件系统视图，并辅以 seccomp 限制系统调用","使用 SELinux 或 AppArmor 安全模块，通过强制访问控制（MAC）进行拦截"],correct:2,explanation:"根据源码，Linux 环境下的沙箱默认使用 codex-linux-sandbox helper，主要依靠 bubblewrap 实现文件系统隔离，配合 seccomp 做系统调用限制，而 Landlock 是作为 fallback 保留的。"},{question:"ExecPolicy（指令策略引擎）在评估一条待执行的命令时，其判定结果包含哪三种状态？",options:["Success（成功）、Failure（失败）、Pending（等待）","Allow（允许）、Forbidden（禁止）、Prompt（要求人工审批）","Execute（执行）、Skip（跳过）、Retry（重试）","Safe（安全）、Warning（警告）、Danger（危险）"],correct:1,explanation:"在 execpolicy/src/decision.rs 中，策略引擎对命令的判定结果为 Allow、Forbidden 或 Prompt，进入 core 流程后转换为相应的 ExecApprovalRequirement。"},{question:"Codex 的 Process Hardening（进程加固）模块的主要职责是什么？",options:["在每次执行子进程前清洗 PATH 等环境变量，并重置工作目录（CWD）以防止逃逸","在主程序启动时进行全局自保，如禁用 Core Dump、禁止 ptrace attach，防止被调试或动态库劫持","动态生成 macOS 的 .sbpl 策略文件，拦截所有的网络访问请求","对模型生成的代码进行静态安全扫描，拦截潜在的 SQL 注入或恶意载荷"],correct:1,explanation:"process-hardening 主要在 Pre-main 阶段运行，用于保护代理主进程自身的内存与执行环境纯净。执行时的环境变量清洗和 CWD 重置则属于执行请求构造和沙箱的职责。"},{question:"从沙箱与安全机制的实现角度来看，采用 Rust 作为核心语言的工程优势之一是什么？",options:["Rust 的包管理器 Cargo 提供了比 npm 更严格的自动代码审计，防止了供应链攻击","Rust 的异步生成器（Async Generator）天然支持多 Agent 环境下的隔离并发执行","相比于 Node.js，Rust 更便于调用内核级沙箱 API 并精细控制子进程与系统资源","Rust 的编译速度远超 TypeScript，极大缩短了本地 Agent 系统的安装时间"],correct:2,explanation:"要实现深度的进程级沙箱隔离（如配置 bubblewrap 或 sandbox-exec 参数）以及系统级的自保护（禁用 ptrace 等），贴近操作系统的系统编程能力是 Rust 相比 TS 等语言的显著工程优势。"}];return(x,e)=>{const a=c("Quiz");return d(),r("div",null,[e[0]||(e[0]=n("",41)),i(a,{questions:o})])}}});export{u as __pageData,m as default};
